-- 이벤트 obsidian_db_2.ev_cleanup_daily_notes 구조 내보내기
DELIMITER //
CREATE EVENT `ev_cleanup_daily_notes` ON SCHEDULE EVERY 1 DAY STARTS '2025-09-03 15:43:58' ON COMPLETION NOT PRESERVE ENABLE DO DELETE FROM daily_notes
  WHERE created_at < DATE_SUB(NOW(), INTERVAL 1 MONTH)//
DELIMITER ;

-- 함수 obsidian_db_2.fn_acl_can 구조 내보내기
DELIMITER //
CREATE FUNCTION `fn_acl_can`(p_resource_type VARCHAR(32),
  p_resource_pk   BIGINT UNSIGNED,
  p_user_id       BIGINT UNSIGNED,
  p_mode          CHAR(1)
) RETURNS tinyint(1)
    DETERMINISTIC
BEGIN
  DECLARE v_policy VARCHAR(3);
  DECLARE v_owner BIGINT;
  DECLARE v_allow TINYINT(1);

  SELECT policy_code, owner_user_id INTO v_policy, v_owner
  FROM acl_bindings
  WHERE resource_type=p_resource_type AND resource_pk=p_resource_pk
  LIMIT 1;

  IF v_policy IS NULL THEN
    RETURN 0;
  END IF;

  IF v_owner = p_user_id THEN
    IF p_mode='r' THEN SELECT owner_r INTO v_allow FROM perm_policies WHERE policy_code=v_policy;
    ELSEIF p_mode='w' THEN SELECT owner_w INTO v_allow FROM perm_policies WHERE policy_code=v_policy;
    ELSEIF p_mode='x' THEN SELECT owner_x INTO v_allow FROM perm_policies WHERE policy_code=v_policy;
    END IF;
    RETURN v_allow;
  END IF;

  
  IF p_mode='r' THEN SELECT other_r INTO v_allow FROM perm_policies WHERE policy_code=v_policy;
  ELSEIF p_mode='w' THEN SELECT other_w INTO v_allow FROM perm_policies WHERE policy_code=v_policy;
  ELSEIF p_mode='x' THEN SELECT other_x INTO v_allow FROM perm_policies WHERE policy_code=v_policy;
  END IF;

  RETURN v_allow;
END//
DELIMITER ;

-- 테이블 obsidian_db_2.kb_sync_jobs 구조 내보내기
CREATE TABLE IF NOT EXISTS `kb_sync_jobs` (
  `job_id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `kb_id` bigint(20) unsigned NOT NULL,
  `scope` enum('KB','PROJECT','NODE','OBJECT') NOT NULL DEFAULT 'KB',
  `target_id` bigint(20) unsigned DEFAULT NULL,
  `action` enum('FULL_SYNC','UPSERT','DELETE') NOT NULL DEFAULT 'FULL_SYNC',
  `status` enum('QUEUED','RUNNING','SUCCESS','FAILED') NOT NULL DEFAULT 'QUEUED',
  `try_count` int(10) unsigned NOT NULL DEFAULT 0,
  `last_error` text DEFAULT NULL,
  `requested_by` bigint(20) unsigned DEFAULT NULL,
  `requested_at` datetime NOT NULL DEFAULT current_timestamp(),
  `finished_at` datetime DEFAULT NULL,
  PRIMARY KEY (`job_id`),
