-- 트리거 obsidian_db_2.trg_storage_objects_acl_ai 구조 내보내기
SET @OLDTMP_SQL_MODE=@@SQL_MODE, SQL_MODE='STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION';
DELIMITER //
CREATE TRIGGER trg_storage_objects_acl_ai
AFTER INSERT ON storage_objects
FOR EACH ROW
BEGIN
  
  VALUES('STORAGE_OBJECT', NEW.object_id, NEW.org_id, 'S3', NEW.owner_user_id);
END//
DELIMITER ;
SET SQL_MODE=@OLDTMP_SQL_MODE;

-- 트리거 obsidian_db_2.trg_tree_nodes_acl_ai 구조 내보내기
SET @OLDTMP_SQL_MODE=@@SQL_MODE, SQL_MODE='STRICT_TRANS_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION';
DELIMITER //
CREATE TRIGGER trg_tree_nodes_acl_ai
AFTER INSERT ON tree_nodes
FOR EACH ROW
BEGIN
  DECLARE v_org BIGINT UNSIGNED;
  DECLARE v_is_user_kb TINYINT(1);

  SELECT t.org_id, t.is_user_kb
    INTO v_org, v_is_user_kb
  FROM trees t
  WHERE t.tree_id = NEW.tree_id;

  
  VALUES('TREE_NODE', NEW.node_id, v_org, IF(v_is_user_kb=1,'S1','S3'), NEW.created_by)
  ON DUPLICATE KEY UPDATE
    policy_code = VALUES(policy_code),
    owner_user_id = VALUES(owner_user_id);
END//
DELIMITER ;
SET SQL_MODE=@OLDTMP_SQL_MODE;

-- 트리거 obsidian_db_2.trg_tree_nodes_ai 구조 내보내기
SET @OLDTMP_SQL_MODE=@@SQL_MODE, SQL_MODE='STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION';
DELIMITER //
CREATE TRIGGER trg_tree_nodes_ai
AFTER INSERT ON tree_nodes
FOR EACH ROW
BEGIN
  CALL sp_tree_add_node(NEW.node_id);
END//
DELIMITER ;
SET SQL_MODE=@OLDTMP_SQL_MODE;

